function openRpcConn(host, port) {
  const sock = net.connect({ host, port });
  // default socket options
  return sock;
}

async function call(sock, reqBytes) {
  sock.write(reqBytes);          // small request, ~80 bytes
  const res = await readFrame(sock);
  if (res.error) {
    throw new Error(res.error);  // bail out on a protocol error
  }
  return res.body;
}

// the connection is meant to stay open and idle between bursts of calls
